def _p(url, title, h1, description, intro, blocks, rail, prio="0.7"):
    return {
        "url": url, "title": title, "h1": h1, "description": description,
        "intro": intro, "blocks": blocks, "rail": rail, "priority": prio,
        "crumb_labels": CRUMB,
    }


